-- 0001 — the platform tables of CONTRACT-JOB@0.1.
--
-- This file is the authoritative schema the contract points at. Column order and
-- index choices are implementation detail; the fields, types, and nullability are
-- the contract, and every constraint below names the invariant it exists to hold.
--
-- Two rules from the contract shape the whole file.
--
--   * "Ordering, time, and identity" — every timestamp is timestamptz and is
--     generated by the database. Application clocks are never consulted for a
--     lease or availability decision, so a skew between two worker processes
--     cannot violate I2. Hence `default now()` rather than a value passed in.
--   * Enumerated columns are `text` with a CHECK, not a PostgreSQL enum type. The
--     contract states the type as `text`, an enum would make the column's
--     information_schema type something else, and the contract's own
--     compatibility statement expects P0-B to change the state machine — a CHECK
--     is replaced by one migration, while an enum value can be added but never
--     removed.
--
-- `schema_migrations` is not created here. The applier has to read it before it
-- can know whether this file has run, so it bootstraps that table itself; see
-- platform_core/db/migrate.py.

create table job (
  id               uuid        primary key,
  handler          text        not null,
  -- Required, but JSON `null` is a legal value: the contract's "Explicit null"
  -- rule says the platform passes it through and lets the handler interpret it.
  -- `not null` on the column with `'null'::jsonb` as a permitted value is exactly
  -- that distinction, which a nullable column would erase.
  payload          jsonb       not null,
  state            text        not null,
  attempt_count    integer     not null default 0,
  max_attempts     integer     not null,
  available_at     timestamptz not null default now(),
  lease_owner      text,
  lease_expires_at timestamptz,
  terminal_reason  text,
  correlation_id   text        not null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),

  constraint job_state_is_known
    check (state in ('PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED')),

  -- I4, lower half: an attempt budget below one describes a job that can never
  -- run and could never reach a terminal state, which I3 forbids.
  constraint job_budget_is_at_least_one
    check (max_attempts >= 1),

  -- I4, upper half: attempt_count never exceeds max_attempts. Reaching the budget
  -- forces a terminal transition, so a row above it is a state machine defect and
  -- the database is the cheapest place to find out.
  constraint job_attempts_stay_within_budget
    check (attempt_count >= 0 and attempt_count <= max_attempts),

  -- "Not applicable" in the contract: lease_owner and lease_expires_at are null
  -- outside RUNNING, and a RUNNING job by definition has a holder and a deadline.
  -- Written as an equivalence so both directions are enforced.
  constraint job_lease_is_held_exactly_while_running
    check ((state = 'RUNNING') = (lease_owner is not null)),
  constraint job_lease_expiry_is_set_exactly_while_running
    check ((state = 'RUNNING') = (lease_expires_at is not null)),

  -- terminal_reason is the error class for FAILED and null for SUCCEEDED. It is
  -- also null before the job is terminal, so FAILED is the only state that may
  -- carry one.
  constraint job_terminal_reason_belongs_to_failure
    check (terminal_reason is null or state = 'FAILED')
);

-- The two halves of the single claim statement. The contract requires one
-- statement to handle dispatch and recovery together, over rows that are PENDING
-- and due or RUNNING with an expired lease, so each half gets the partial index
-- that makes its predicate selective. Partial rather than plain, because terminal
-- jobs accumulate and are never claimable.
create index job_due_while_pending on job (available_at) where state = 'PENDING';
create index job_lease_deadline_while_running on job (lease_expires_at) where state = 'RUNNING';

create table job_attempt (
  id             uuid        primary key,
  job_id         uuid        not null references job (id),
  attempt_no     integer     not null,
  worker_id      text        not null,
  started_at     timestamptz not null default now(),
  finished_at    timestamptz,
  outcome        text,
  error_class    text,
  error_summary  text,
  -- Protected debug detail. Never returned by the API by default; reaches logs
  -- only at debug level. The protection is in the application types — this column
  -- only stores what they already redacted.
  error_detail   jsonb,
  correlation_id text        not null,

  constraint job_attempt_number_is_one_based
    check (attempt_no >= 1),

  constraint job_attempt_outcome_is_known
    check (
      outcome is null
      or outcome in ('SUCCEEDED', 'RETRYABLE_FAILURE', 'PERMANENT_FAILURE', 'ABANDONED')
    ),

  -- The contract marks both finished_at and outcome "null while open", so they
  -- are two views of one fact and may not disagree. A closed attempt without an
  -- outcome would also read as open to the I2 index below, which is the failure
  -- this rules out.
  constraint job_attempt_closes_with_an_outcome
    check ((finished_at is null) = (outcome is null)),

  -- Within one job, attempt_no is strictly increasing and unique.
  constraint job_attempt_number_is_unique_per_job
    unique (job_id, attempt_no)
);

-- I2 — no conflicting active ownership. At most one open attempt per job, held by
-- the database rather than by the code that writes attempts.
--
-- This is one half of the invariant. It makes a second open attempt impossible,
-- which is what a reclaim races to create. The other half is the fencing rule at
-- completion time: a worker that stalls past its lease and wakes up late is
-- refused because its own attempt is no longer open. Neither half implies the
-- other, and JOB-006 is the scenario for the half that lives above SQL.
create unique index job_attempt_one_open_per_job
  on job_attempt (job_id)
  where finished_at is null;

-- The only durable effect a P0-A handler may produce (DP-006 D8).
create table platform_effect (
  -- I1 — a single durable effect per key. The primary key is the entire
  -- idempotency mechanism: the handler chooses a key independent of the attempt
  -- number, and a repeated delivery collides here instead of writing twice.
  effect_key text        primary key,
  job_id     uuid        not null references job (id),
  applied_at timestamptz not null default now(),
  -- Opaque synthetic value with no schema, no version, and no identity semantics.
  -- Structure here would turn this table into something P0-A is not allowed to
  -- have, so it stays nullable and uninterpreted.
  payload    jsonb
);

create index platform_effect_by_job on platform_effect (job_id);
